#include <iostream>
using namespace std;

void swap_coords(int &a, int &b) {
    int temp = a;
    a = b;
    b = temp;
}

int main() {
    int x, y;
    cin >> x >> y;

    swap_coords(x, y);
    cout << "COORDINATES: " << x << " " << y << endl;

    return 0;
}

