#include <iostream>
#include <vector>
using namespace std;

int count_valid(const vector<int> &v, int threshold) {
    int c = 0;
    for (int i = 0; i < v.size(); i++) {
        if (v[i] >= threshold) c++;
    }
    return c;
}

int main() {
    vector<int> sensors = {85, 120, 40, 150, 95};
    int res = count_valid(sensors, 100);
    cout << "ABOVE: " << res << " TOTAL: " << sensors.size() << endl;
    return 0;
}

